/**
 * P-66.1.1.3.3
 * Nomenclature of Organic Chemistry: IUPAC Recommendations and Preferred Names 2013 (the Blue Book)
 *
 * “Amic acids
 * Amic acids are derivatives of dicarboxylic acids having a retained name and when one carboxylic
 * group has been changed to a carboxamide group. Preferred IUPAC names for amic acids are generated by
 * method (1) in P-66.1.1.4.1.1. They may also be named by methods (2) and (3) and by replacing the ‘ic
 * acid’ ending in the retained name by ‘amic acid’ (see P-65.1.6.1).”
 *
 * Examples with a drawing are drawn, not written out, in the Blue Book. The checks read
 * their names, but can only check the structure against the drawing once the drawings are used.
 */
import { checkRule } from '../support/checkRule.js';

checkRule('P-66.1.1.3.3', [
  // Drawn in the Blue Book.
  { drawing: 'P6agif/P66113l.gif', pin: '10-amino-10-oxodecanoic acid', otherNames: ['9-carbamoylnonanoic acid', '9-(aminocarbonyl)nonanoic acid'] },
  // Drawn in the Blue Book.
  { drawing: 'P6agif/P66113m.gif', pin: '3-amino-3-oxopropanoic acid', otherNames: ['carbamoylacetic acid', '(aminocarbonyl)acetic acid', 'malonamic acid'] },
]);
